from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[1];checks=[]
def read(p):return json.loads((R/p).read_text())
def ck(b,n):checks.append(dict(name=n,passed=bool(b)));assert b,n
m=read('04-table/T01-second-challenge-map.json');cids={r['claim_id'] for r in read('02-evidence/registers/claims.json')['records']};conds={x['condition_id']:x for x in m['conditions']}
# Root analyst-applied constructed cases. No participant case, market estimate,
# behavioural simulation or empirical validation is created by these records.
routes=[
('TR01','Equivalent free research copy','A hypothetical contributor already receives the promised research free. The same employer is pencilled in for a licence with equivalent access.',['TC01','TC06'],'Do not forecast an automatic second sale. Preserve the free benefit, establish incremental use/service/rights and count the actual bundle once.',['No new restriction on free benefit','No assumed paid buyer or revenue'],['CLM-0522','CLM-0506']),
('TR02','Adviser client-facing reuse','A hypothetical adviser likes a report for a client deliverable, without an external-use agreement.',['TC01','TC02'],'Identify actual intended client use and applicable permissions; neither internal access nor the adviser label establishes resale/client publication rights.',['No external rights presumed','No licence or price adopted'],['CLM-0506','CLM-0515']),
('TR03','Funder-targeted recruitment','A hypothetical funder wants invited sales targets and private meeting access while the council promises a relevant confidential practitioner group.',['TC02','TC04','TC06'],'Separate research/member eligibility from optional commercial access; test fit and transparent deliverable rights. Funding does not create a participant list or guarantee access.',['No sponsor list prepopulated','No private identities or answers granted'],['CLM-0508','CLM-0509']),
('TR04','Public moderator role','A retained public summit retrospective names Nick as moderator.',['TC02','TC03'],'Record that public dated role; do not infer a current formal partnership, available audience, permission or Table endorsement.',['Public involvement retained','Broader shell-only collaboration lead unconfirmed'],['CLM-0500']),
('TR05','Programme and member change','A hypothetical four-city programme uses different people; one professional changes employer between contributions.',['TC03'],'Keep programme, cohort, person, role and entitlement period distinct. Do not infer a longitudinal panel, achieved retention, blanket permission expiry or automatic transfer.',['No participant record invented','Actual eligible report person counts once under WP03'],['CLM-0498','CLM-0501','CLM-0503','CLM-0510']),
('TR06','Rule meeting and recording checkbox','A hypothetical session is designated under the Chatham House Rule but an old generic permission form offers recording.',['TC05'],'The chosen mode governs this meeting; a checkbox does not silently override it. Do not record or attribute under that mode. Separately approved research interviews may use different terms.',['No actual meeting mode adopted','No universal ban imposed on all research'],['CLM-0518','CLM-0519']),
('TR07','Hospitality constraint and remote input','A hypothetical eligible practitioner cannot accept hospitality under their employer rules but might give permitted written input.',['TC04','TC05'],'Evaluate permitted research contribution separately from attendance. A relevant remote account may count only if actual, verified, eligible, usable and permissioned; it is not an attended event.',['Employer-specific example not universalised','No attendance or contribution counted in advance'],['CLM-0520','CLM-0521']),
('TR08','Funds before deliverable readiness','A hypothetical partner payment arrives before evidence rights, eligible audience and a promised briefing are ready.',['TC03','TC06'],'Separate received funds, deliverable obligations, staffing/rights readiness and actual fulfilled benefit. Cash receipt does not prove viability, retention or that the programme can be delivered.',['No competitor invoice interval copied','No paid receipt or forecast entered'],['CLM-0509','CLM-0510','CLM-0516']),
('TR09','Dublin location versus research decision','A hypothetical participant is interested in a Dublin event but needs an Irish payroll compliance answer already available through local support.',['TC01','TC04'],'Compare alternatives for the actual decision/country scope. Event interest does not establish demand for global investment research or a research licence.',['No Irish/global demand rate inferred','IPASS and GPA remain substitutes, not seventh/eighth selected models'],['CLM-0504','CLM-0505','CLM-0507'])]
apps=[]
for i,title,input_,cs,result,limits,claims in routes:
 ck(set(cs)<=set(conds),'condition IDs resolve '+i);ck(set(claims)<=cids,'claim IDs resolve '+i)
 ck(bool(result)and len(limits)==2,'bounded assessment recorded '+i)
 ck(all(not conds[c]['mandatory'] and not conds[c]['scored'] and not conds[c]['validated'] for c in cs),'selective nonvalidated conditions '+i)
 apps.append(dict(route_id=i,title=title,constructed_input=input_,condition_ids=cs,root_analyst_assessment=result,limits=limits,claim_ids=claims,assessment_completed=True,actual_participant_case=False,empirical_validation=False,financial_input_created=False))
for r in read('08-qa/T01-second-check-baseline.json')['files']:ck(hashlib.sha256((R/r['path']).read_bytes()).hexdigest()==r['sha256'],'131preservation '+r['path'])
ck(m['selected_model_ids']==[f'T01-M{i:02}'for i in range(1,7)]and not m['hypotheses_replaced'],'firstsixmodels/fourhypotheses unchanged')
ck(m['additional_mandatory_questions']==0 and m['participant_observations']==[] and m['actual_Table_conversations']==[] and m['financial_inputs']==[] and m['new_price_recommendations']==[],'no expanded core/actual/financial claims')
for p in ['05-analysis/observations.json','05-analysis/charts.json','04-table/financial-inputs.json']:ck(read(p)['records']==[],'actual data empty '+p)
ck(not read('01-method/collection-pack-v0.1/REVIEW-DECISIONS.json')['collection_ready'],'collection not activated')
out=dict(date='2026-10-30',status='passed_internal_constructed_T01_second_challenge_walkthrough',route_count=len(apps),check_count=len(checks),checks=checks,routes=apps,scope='Root analyst applications to hypothetical cases and one dated public-role example; integrity checks are not evidence of buyer behaviour, practitioner usefulness or commercial viability.',actual_participant_cases=0,practitioner_validation=False,commercial_validation=False,new_mandatory_questions=0,financial_inputs_added=0,external_contact=False,model_path='04-table/T01-second-challenge-map.json',model_sha256_at_walkthrough=hashlib.sha256((R/'04-table/T01-second-challenge-map.json').read_bytes()).hexdigest())
(R/'08-qa/T01-second-routing-walkthrough.json').write_text(json.dumps(out,indent=2,ensure_ascii=False)+'\n')
print(json.dumps(dict(status=out['status'],route_count=len(apps),check_count=len(checks))))
